def orgqr_kernel(
    inp,
    tau,
    out,
    M,
    N,
    K,
    input_batch_stride,
    input_row_stride,
    input_col_stride,
    tau_batch_stride,
    out_batch_stride,
    out_row_stride,
    out_col_stride,
    COL_MAJOR_IN: tl.constexpr,
    BLOCK_M: tl.constexpr,
    BLOCK_N: tl.constexpr,
):
    batch = tl.program_id(0)
    col_start = tl.program_id(1) * BLOCK_N
    cols = col_start + tl.arange(0, BLOCK_N)
    rows = tl.arange(0, BLOCK_M)
    row_mask = rows < M
    col_mask = cols < N

    input_base = inp + batch * input_batch_stride
    tau_base = tau + batch * tau_batch_stride
    out_base = out + batch * out_batch_stride

    # The state tile is kept column-major (``[BLOCK_N, BLOCK_M]``) so the M
    # axis is the trailing/contiguous one: the per-iteration vector ops
    # (reflector build, broadcast) and the axis-1 reduction then stay
    # lane-local instead of paying cross-lane layout conversions, which
    # dominated the row-major-tile variant (3.4x measured at 128x64).
    # ``q`` also stays in registers through the whole sweep: each program owns
    # a disjoint (batch, column-block) tile, so re-reading it from HBM per
    # iteration only added K+1 full-tile round trips.
    q_t = tl.where(rows[None, :] == cols[:, None], 1.0, 0.0).to(inp.dtype.element_ty)

    for k_idx in range(K - 1, -1, -1):
        tau_k = tl.load(tau_base + k_idx)
        if COL_MAJOR_IN:
            # Row stride 1 folds at compile time, leaving a bare ``arange``
            # span: the lowering emits one coalesced vector load. A runtime
            # row stride keeps the offsets affine-but-unknown and degrades
            # to one access per element at ~ns/element.
            input_col = tl.load(
                input_base + k_idx * input_col_stride + rows,
                mask=row_mask,
                other=0.0,
            )
        else:
            input_col = tl.load(
                input_base + rows * input_row_stride + k_idx * input_col_stride,
                mask=row_mask,
                other=0.0,
            )
        v = tl.where(
            rows > k_idx,
            input_col,
            tl.where(rows == k_idx, 1.0, 0.0),
        )
        dots = tl.sum(q_t * v[None, :], axis=1)
        q_t -= tau_k * v[None, :] * dots[:, None]
    # Explicit transpose back to the row-major store orientation: a directly
    # transposed-oriented store mis-addresses small tiles on this backend
    # (silent wrong values at e.g. [8, 8], measured on 7x5 K=0).
    tl.store(
        out_base + rows[:, None] * out_row_stride + cols[None, :] * out_col_stride,
        tl.trans(q_t),
        mask=row_mask[:, None] & col_mask[None, :],
    )


def _validate_orgqr(input, tau, out=None):
    if input.ndim < 2:
        raise RuntimeError("orgqr: input must have at least 2 dimensions")
    if tau.ndim != input.ndim - 1 or tau.shape[:-1] != input.shape[:-2]:
        raise RuntimeError("orgqr: tau batch dimensions must match input")
    if input.shape[-2] < input.shape[-1]:
        raise RuntimeError(
            "orgqr: input.shape[-2] must be greater than or equal to input.shape[-1]"
        )
    if tau.shape[-1] > input.shape[-1]:
        raise RuntimeError(
            "orgqr: input.shape[-1] must be greater than or equal to tau.shape[-1]"
        )
    if input.dtype != tau.dtype or input.device != tau.device:
        raise RuntimeError("orgqr: input and tau must have the same dtype and device")
    if input.is_complex():
        raise RuntimeError(
            "orgqr: complex dtypes are not supported by this Triton kernel"
        )
    if input.dtype not in (torch.float32, torch.float64):
        raise RuntimeError("orgqr: only float32 and float64 inputs are supported")
    if out is not None:
        if out.device != input.device:
            raise RuntimeError("orgqr: input and out must be on the same device")
        if not torch.can_cast(input.dtype, out.dtype):
            raise RuntimeError(
                f"orgqr: result dtype {input.dtype} cannot be safely cast to {out.dtype}"
            )


