            input_work,
            tau_work,
            out_work,
            m,
            n,
            k,
            input_work.stride(0),
            input_work.stride(1),
            input_work.stride(2),
            tau_work.stride(0),
            out_work.stride(0),
            out_work.stride(1),
            out_work.stride(2),
            COL_MAJOR_IN=col_major_in,
            BLOCK_M=block_m,
            BLOCK_N=block_n,
            num_warps=1,
